window.MeadowFallback={create(canvas){const ctx=canvas.getContext("2d"),flowers=[];let time=0;let seed=17;function rand(){seed=(seed*16807)%2147483647;return seed/2147483647;}
for(let i=0;i<140;i++)flowers.push({x:120+rand()*960,y:170+rand()*480,s:rand(),c:['#faf4cc','#f4deb6','#e4ecbf'][i%3]});
function ell(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
function path(points,color,width){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}
function tree(x,y,s=1){ell(x+7,y+13,31*s,11*s,'#647d3920');path([[x,y],[x,y-40*s]],'#a28a55',8*s);ell(x-15*s,y-45*s,22*s,24*s,'#91ad5d');ell(x+13*s,y-48*s,25*s,30*s,'#7f9e50');ell(x-4*s,y-66*s,26*s,24*s,'#9ebc6b');ell(x-12*s,y-73*s,12*s,8*s,'#afca7b');}
function background(){ctx.clearRect(0,0,1200,760);ctx.fillStyle='#e8ebcf';ctx.fillRect(0,0,1200,760);ell(605,432,547,280,'#cad8a3');ell(600,415,526,265,'#b8ce89');ell(772,315,290,160,'#c4d995');ell(360,485,242,180,'#b2cb80');ell(819,537,248,116,'#b7ce83');
path([[395,170],[373,248],[385,319],[346,390],[354,460],[312,548],[324,644]],'#edf0c8',37);path([[395,170],[373,248],[385,319],[346,390],[354,460],[312,548],[324,644]],'#89bcc0',26);path([[391,173],[369,246],[381,320],[342,390],[350,460],[308,549],[320,643]],'#b7dbce',5);
path([[758,172],[714,260],[754,351],[727,429],[762,523],[720,658]],'#dbcfa1',39);path([[758,172],[714,260],[754,351],[727,429],[762,523],[720,658]],'#e5dab0',24);
// Little footbridge.
ctx.save();ctx.translate(354,430);ctx.rotate(.10);ctx.fillStyle='#b39160';ctx.fillRect(-39,-22,78,44);for(let i=-34;i<36;i+=12)path([[i,-21],[i,21]],'#dfbf85',9);path([[-42,-25],[42,-25]],'#9e8256',5);path([[-42,25],[42,25]],'#9e8256',5);ctx.restore();
for(const f of flowers){if(Math.abs(f.x-750)<35||Math.abs(f.x-350)<38)continue;path([[f.x,f.y],[f.x-2,f.y-5-f.s*4]],'#8faa61',1.4);if(f.s>.55){ell(f.x-2,f.y-8,3,3,f.c);ell(f.x-2,f.y-8,1.2,1.2,'#c3a45d');}}
// Fence along the far edge.
for(let x=482;x<665;x+=35){path([[x,179],[x,152]],'#f0e6bd',6);}path([[477,163],[665,163]],'#f0e6bd',5);
tree(186,254,1.1);tree(275,165,.8);tree(952,205,1.15);tree(1054,420,.95);tree(170,567,.9);tree(972,638,.85);
// Warm little pond and stepping stones.
ell(918,493,66,35,'#a3c7b7');ell(918,489,60,29,'#99c5c5');path([[887,487],[910,484]],'#c4e0d4',3);path([[930,499],[948,495]],'#c4e0d4',3);ell(865,515,11,5,'#d5d4ac');ell(979,479,13,6,'#dedbb9');}
function drawSheep(s,ghost=false){let x=s.x,y=s.y,z=s.z;ctx.save();ctx.globalAlpha=ghost?.6:1;ell(x,y+8,30-z*.035,10-z*.009,'#526d3b26');ctx.translate(x,y-z);if(s.ko>0)ctx.rotate(Math.PI);const bounce=s.z===0?Math.sin(s.walk)*2:0;ctx.translate(0,bounce);ctx.rotate(s.heading);const leg=Math.sin(s.walk)*4;path([[-18,-4],[-18+leg,13]],'#665d4b',6);path([[11,-4],[11-leg,13]],'#665d4b',6);ell(-3,-18,32,24,'#e6e1c9');for(let i=0;i<9;i++){const a=i/9*Math.PI*2;ell(-5+Math.cos(a)*24,-20+Math.sin(a)*17,13,12,'#fff9e5');}ell(-7,-21,26,17,'#fff9e5');ell(-36,-19,7,6,'#fff9e5');ctx.save();const reach=s.bite>0?Math.sin(s.bite/.45*Math.PI)*26:0;if(reach)path([[8,-15],[22+reach,-15]],'#eee6cd',18);ctx.translate(reach,0);ell(22,-17,14,18,'#6f6654');ell(15,-30,10,5,'#80745c');ell(34,-27,9,5,'#80745c');if(s.ko>0){path([[24,-23],[30,-17]],'#fff9e5',2);path([[30,-23],[24,-17]],'#fff9e5',2);}else{ell(27,-20,2.6,3.5,'#fff9e5');ell(28,-19,1.4,2,'#2d3e32');}if(s.bite>0){ell(35,-9,8,8,'#443e31');path([[32,-14],[39,-13]],'#fff7df',3);}ell(33,-9,2,1.2,'#403b30');path([[14,-3],[31,-3]],s.color,5);
ctx.save();ctx.translate(22,-28);ctx.scale(1.5,1.5);ctx.translate(-22,28);if(s.hat===1){ell(22,-36,22,5,'#d5ad5d');ell(21,-43,13,10,'#e6c577');path([[10,-38],[32,-38]],s.color,4);}if(s.hat===2){ctx.fillStyle=s.color;ctx.beginPath();ctx.moveTo(8,-33);ctx.lineTo(22,-64);ctx.lineTo(35,-33);ctx.fill();ell(22,-62,4,4,'#fff7df');}if(s.hat===3){path([[8,-34],[31,-35]],'#8b9e61',5);for(let i=0;i<4;i++)ell(10+i*7,-36-(i%2)*4,5,5,['#e5a4aa','#fff0af'][i%2]);}ctx.restore();ctx.restore();ctx.restore();
ctx.save();ctx.textAlign='center';ctx.font='bold 11px Arial';ctx.fillStyle='#4f6545';ctx.fillText(ghost?'':('P'+(s.n+1)+(s.ko>0?' · '+Math.ceil(s.ko)+'s':'')),x,y-z-62-(s.hat===2?20:0));if(!ghost){ctx.fillStyle='#fff9e5';ctx.fillRect(x-22,y-z-58,44,5);ctx.fillStyle=s.health>1?'#779f60':'#c07a68';ctx.fillRect(x-22,y-z-58,44*s.health/3,5);}if(s.baa>0){ctx.fillStyle='#fffdf1';ctx.beginPath();ctx.roundRect(x-29,y-z-109,58,28,12);ctx.fill();ctx.fillStyle='#667854';ctx.font='bold 13px Georgia';ctx.fillText('Baaa!',x,y-z-90);}ctx.restore();}
return {begin:background,sheep:drawSheep,render(t){time=t;}};}};